// ─── File: src/main/java/com/bank/batch/service/BatchProcessorService.java ───
package com.bank.batch.service;

import com.bank.batch.dto.BatchResult;
import com.bank.batch.model.Transaction;
import com.bank.batch.repository.TransactionRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

@Service
@RequiredArgsConstructor
@Slf4j
public class BatchProcessorService {

    private final TransactionRepository txnRepo;

    @Value("${batch.max-process-limit:5}")
    private int maxProcessLimit;

    // ═══ APPROACH 1: AtomicInteger (RECOMMENDED) ═══
    @Transactional(readOnly = true)
    public BatchResult processWithAtomicInteger() {
        List<Transaction> all = txnRepo.findAll();

        // AtomicInteger: reference is effectively final, value is mutable
        AtomicInteger scanCount = new AtomicInteger(0);
        AtomicInteger filterPassCount = new AtomicInteger(0);
        AtomicReference<BigDecimal> runningTotal = new AtomicReference<>(BigDecimal.ZERO);

        // int maxLimit = maxProcessLimit; // effectively final — captured by lambda
        int maxLimit = maxProcessLimit;

        List<String> processed = all.stream()
            .peek(t -> scanCount.incrementAndGet())  // count scanned
            .filter(Transaction::isPending)
            .peek(t -> filterPassCount.incrementAndGet())  // count passed filter
            .sorted(Comparator.comparingInt(Transaction::getPriority).reversed())
            .limit(maxLimit)  // maxLimit is effectively final int — OK!
            .peek(t -> runningTotal.updateAndGet(prev -> prev.add(t.getAmount())))
            .map(Transaction::getTxnId)
            .toList();

        log.info("[AtomicInteger] Scanned: {}, Passed filter: {}, Processed: {}, Total: Rs.{}",
            scanCount.get(), filterPassCount.get(), processed.size(), runningTotal.get());

        return new BatchResult("AtomicInteger", scanCount.get(),
            filterPassCount.get(), processed.size(), runningTotal.get(), processed,
            "AtomicInteger reference is final, internal value mutated via CAS — thread-safe!");
    }

    // ═══ APPROACH 2: final int[] (NOT thread-safe) ═══
    @Transactional(readOnly = true)
    public BatchResult processWithFinalArray() {
        List<Transaction> all = txnRepo.findAll();

        // final int[]: array reference is final, contents are mutable
        final int[] scanCount = {0};
        final int[] filterPassCount = {0};
        final BigDecimal[] runningTotal = {BigDecimal.ZERO};

        List<String> processed = all.stream()  // sequential — int[] is OK
            .peek(t -> scanCount[0]++)
            .filter(Transaction::isPending)
            .peek(t -> filterPassCount[0]++)
            .sorted(Comparator.comparingInt(Transaction::getPriority).reversed())
            .limit(maxProcessLimit)
            .peek(t -> runningTotal[0] = runningTotal[0].add(t.getAmount()))
            .map(Transaction::getTxnId)
            .toList();

        log.info("[int[]] Scanned: {}, Passed: {}, Processed: {}", 
            scanCount[0], filterPassCount[0], processed.size());

        return new BatchResult("final int[]", scanCount[0],
            filterPassCount[0], processed.size(), runningTotal[0], processed,
            "Array reference is final, contents mutable — NOT thread-safe for parallel!");
    }

    // ═══ APPROACH 3: Effectively final local (read-only) ═══
    @Transactional(readOnly = true)
    public BatchResult processWithEffectivelyFinal() {
        List<Transaction> all = txnRepo.findAll();

        // These are effectively final — never reassigned after initialization
        BigDecimal minAmount = new BigDecimal("40000");  // effectively final
        String targetAccount = "SAV2001";                 // effectively final

        // CANNOT do: minAmount = new BigDecimal("50000"); // would break effectively final!

        List<String> processed = all.stream()
            .filter(Transaction::isPending)
            .filter(t -> t.getAmount().compareTo(minAmount) >= 0)  // captures minAmount
            .filter(t -> t.getAccountId().equals(targetAccount))    // captures targetAccount
            .sorted(Comparator.comparingInt(Transaction::getPriority).reversed())
            .map(Transaction::getTxnId)
            .toList();

        return new BatchResult("effectively final (read-only)", all.size(),
            processed.size(), processed.size(), BigDecimal.ZERO, processed,
            "minAmount and targetAccount are effectively final — captured as read-only copies");
    }
}
```

