package com.bank.batch.controller;

import com.bank.batch.dto.BatchResult;
import com.bank.batch.service.BatchProcessorService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/batch")
@RequiredArgsConstructor
public class BatchController {

    private final BatchProcessorService batchService;

    @GetMapping("/atomic")
    public BatchResult atomic() { return batchService.processWithAtomicInteger(); }

    @GetMapping("/array")
    public BatchResult array() { return batchService.processWithFinalArray(); }

    @GetMapping("/final")
    public BatchResult effectivelyFinal() { return batchService.processWithEffectivelyFinal(); }
}
