// ─── File: src/test/java/com/bank/batch/service/EffectivelyFinalTest.java ───
package com.bank.batch.service;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.RepeatedTest;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.IntStream;
import static org.assertj.core.api.Assertions.*;

class EffectivelyFinalTest {

    // ═══ Effectively final — compiles ═══
    @Test
    void effectivelyFinalCompiles() {
        int threshold = 50000;  // never reassigned → effectively final
        long count = IntStream.of(30000, 60000, 80000)
            .filter(n -> n > threshold)  // captures threshold
            .count();
        assertThat(count).isEqualTo(2);
    }

    // ═══ AtomicInteger workaround ═══
    @Test
    void atomicIntegerWorkaround() {
        AtomicInteger counter = new AtomicInteger(0);
        List<Integer> result = IntStream.rangeClosed(1, 10)
            .filter(n -> {
                counter.incrementAndGet();  // mutable via AtomicInteger
                return n % 2 == 0;
            })
            .boxed().toList();

        assertThat(result).containsExactly(2, 4, 6, 8, 10);
        assertThat(counter.get()).isEqualTo(10);  // all 10 elements were scanned
    }

    // ═══ final int[] workaround ═══
    @Test
    void finalArrayWorkaround() {
        final int[] counter = {0};
        List<Integer> result = IntStream.rangeClosed(1, 5)
            .filter(n -> { counter[0]++; return n > 3; })
            .boxed().toList();

        assertThat(result).containsExactly(4, 5);
        assertThat(counter[0]).isEqualTo(5);
    }

    // ═══ RACE CONDITION with int[] in parallel ═══
    @RepeatedTest(5)
    void finalArrayIsUnsafeInParallel() {
        final int[] unsafeCounter = {0};
        AtomicInteger safeCounter = new AtomicInteger(0);

        IntStream.rangeClosed(1, 100_000)
            .parallel()
            .filter(n -> {
                unsafeCounter[0]++;         // RACE CONDITION! Lost updates!
                safeCounter.incrementAndGet(); // SAFE — CAS operation
                return n % 2 == 0;
            })
            .toArray();

        // safeCounter is always 100,000 (correct)
        assertThat(safeCounter.get()).isEqualTo(100_000);
        // unsafeCounter is often LESS than 100,000 (lost updates!)
        // We can't assert exact value — it's non-deterministic
        // But we CAN assert it's likely corrupted in parallel:
        // (in very rare cases it might be correct, so we just log it)
        System.out.println("unsafe=" + unsafeCounter[0] + " safe=" + safeCounter.get());
    }

    // ═══ Instance field is NOT a local variable — no restriction ═══
    private int instanceCounter = 0;

    @Test
    void instanceFieldHasNoRestriction() {
        instanceCounter = 0;
        List<Integer> result = IntStream.rangeClosed(1, 5)
            .filter(n -> { instanceCounter++; return n > 2; })  // OK — instance field
            .boxed().toList();

        assertThat(result).containsExactly(3, 4, 5);
        assertThat(instanceCounter).isEqualTo(5);
    }
}
